use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;
use std::time::Duration;

use michi_core::pipeline::{Pipeline, PipelineStep, StepStatus};
use michi_core::resilience::RetryConfig;
use michi_pipeline::{step_fn, CircuitBreaker, CancellationToken, ExecutionError, Step, StepDependencies};

#[tokio::main(flavor = "current_thread")]
async fn main() {
    let mut pipeline = Pipeline {
        id: "repro".into(),
        steps: (0..2).map(|_| PipelineStep { id: "a".into(), name: "A".into(), status: StepStatus::Pending }).collect(),
    };
    let deps = StepDependencies::new(&["a".to_string()]).unwrap();
    let count = Arc::new(AtomicU32::new(0));
    let runners: Vec<Box<dyn Step>> = (0..2).map(|_| {
        let count = Arc::clone(&count);
        Box::new(step_fn(move |_| {
            let count = Arc::clone(&count);
            async move { count.fetch_add(1, Ordering::SeqCst); Ok(()) }
        })) as Box<dyn Step>
    }).collect();
    let breaker = Arc::new(CircuitBreaker::new(
        RetryConfig::new(0, Duration::ZERO, Duration::from_millis(1), 0.0),
        Duration::from_secs(1), 2, Duration::from_secs(1),
    ));
    let result = michi_pipeline::execute_pipeline_parallel(
        &mut pipeline, &deps, runners, breaker, 0.0, &CancellationToken::new(),
    ).await;
    println!("duplicate: result={result:?} calls={} statuses={:?}", count.load(Ordering::SeqCst), pipeline.steps.iter().map(|s| s.status).collect::<Vec<_>>());

    let commits = Arc::new(AtomicU32::new(0));
    let commits_step = Arc::clone(&commits);
    let step = step_fn(move |_| {
        let commits = Arc::clone(&commits_step);
        async move {
            commits.fetch_add(1, Ordering::SeqCst);
            std::future::pending::<Result<(), ExecutionError>>().await
        }
    });
    let breaker = CircuitBreaker::new(
        RetryConfig::new(1, Duration::from_millis(1), Duration::from_millis(1), 0.0),
        Duration::from_millis(5), 2, Duration::from_secs(1),
    );
    let result = breaker.call(&step, 0.0).await;
    println!("timeout: result={result:?} commits={}", commits.load(Ordering::SeqCst));
}

